from lib import *
c = boot(video=None, fake_cam=False); inject_synth(c)
# ---------- error set: patient result with the ruler
c.ev("__submit([10,7,10])"); wait(c, "__rehab.state.screen==='result'", 20); time.sleep(3)
r = S_(c); print("   result:", r["status"], r["findings"]); print("  ", r["text"])
check("error set: server corrects it", r["findings"] and r["findings"][0][1] == "error")
check("patient text equals feedback.text exactly", c.ev("document.getElementById('patientText').textContent===__rehab.state.result.feedback.text"))
check("patient plate has a measured-vs-typical ruler built from numbers in the sentence", c.ev("!!__rehab.PP.d.gauge && document.getElementById('patientText').textContent.includes(__rehab.PP.d.gauge.a) && document.getElementById('patientText').textContent.includes(__rehab.PP.d.gauge.b)"))
a = sig(c, "#pplate"); time.sleep(0.7); check("patient plate is animated (current pose plays over the exposures)", a != sig(c, "#pplate"))
click(c, "#rplate"); time.sleep(0.2); p = sig(c, "#pplate"); time.sleep(0.6); check("tap pauses the plate", p == sig(c, "#pplate")); click(c, "#rplate"); time.sleep(0.4); check("tap again resumes", p != sig(c, "#pplate"))
c.shot(f"{S}/shots/g2-result-error.png")
# ---------- clinician view
click(c, "#btnClin"); time.sleep(1.5)
check("clinician: opens", c.ev("__rehab.state.screen==='clinician' && !document.getElementById('cplate').hidden"))
check("clinician: the cited sentence is highlighted with its finding", c.ev("document.querySelectorAll('.sent.on').length===1 && __rehab.state.sel==='F1'"))
check("clinician: details name the finding and show the ruler", c.ev("document.getElementById('det').textContent.includes('Body not tilted') && !!document.querySelector('#det svg.ruler')"))
check("clinician: three ghost poses chosen in the repetition", c.ev("__rehab.state.rp.ghosts.length===3"))
c.ev("__rehab.state.rp.playing=false"); 
click(c, ".sent"); time.sleep(0.8)
check("tap sentence: replay starts", c.ev("__rehab.state.rp.playing===true && document.getElementById('rpPlay').textContent==='Pause'"))
click(c, "#rpPlay"); time.sleep(0.3); check("Pause button pauses", c.ev("__rehab.state.rp.playing===false"))
# drag across the waveform with a real mouse
box = c.ev("(()=>{const r=document.getElementById('wave').getBoundingClientRect(); return [r.left,r.top,r.width,r.height]})()")
c.ev("document.getElementById('cwave').scrollIntoView({block:'center'})"); time.sleep(0.4)
box = c.ev("(()=>{const r=document.getElementById('wave').getBoundingClientRect(); return [r.left,r.top,r.width,r.height]})()")
rp = c.ev("JSON.stringify({t0:__rehab.state.rp.seg[0].t,dur:__rehab.state.rp.dur,tl:__rehab.state.rp.tlDur})"); rp = json.loads(rp)
xAt = lambda t: box[0] + 46 + (box[2] - 46 - 12) * t / rp["tl"]
before = sig(c, "#replay"); out0 = c.ev("document.getElementById('rpOut').textContent")
drag(c, xAt(rp["t0"] + 0.2), box[1] + 90, xAt(rp["t0"] + rp["dur"] * 0.6), box[1] + 90)
time.sleep(0.4); out1 = c.ev("document.getElementById('rpOut').textContent"); pos = c.ev("__rehab.state.rp.pos")
check("scrub: dragging the waveform moves the playhead time", out0 != out1, f"{out0} -> {out1}")
check("scrub: the skeleton moves with it", before != sig(c, "#replay"))
check("scrub: lands where dragged (about 60% of the repetition)", abs(pos / rp["dur"] - 0.6) < 0.1, round(pos / rp["dur"], 2))
c.ev("document.getElementById('wave').focus()"); k0 = c.ev("__rehab.state.rp.pos")
for _ in range(3): c.cmd("Input.dispatchKeyEvent", type="keyDown", key="ArrowRight", code="ArrowRight", windowsVirtualKeyCode=39); c.cmd("Input.dispatchKeyEvent", type="keyUp", key="ArrowRight", code="ArrowRight", windowsVirtualKeyCode=39)
check("keyboard: arrow keys step the replay", c.ev("__rehab.state.rp.pos") > k0)
# sequence layout
c.ev("document.getElementById('cplate').scrollIntoView({block:'start'})"); time.sleep(0.3)
click(c, "#vsw button[data-v=seq]"); time.sleep(0.5)
check("Sequence: contact sheet drawn", c.ev("__rehab.state.view==='seq'") and pixels(c, "#replay") > 100)
c.shot(f"{S}/shots/g2-sequence.png")
rb = c.ev("(()=>{const r=document.getElementById('replay').getBoundingClientRect(); return [r.left,r.top,r.width,r.height]})()")
for t in ("mousePressed", "mouseReleased"): c.cmd("Input.dispatchMouseEvent", type=t, x=rb[0] + rb[2] * 0.75, y=rb[1] + rb[3] * 0.75, button="left", clickCount=1)
time.sleep(0.3); check("Sequence: clicking a frame jumps the replay there", c.ev("__rehab.state.rp.pos") > 0.5 * rp["dur"])
click(c, "#vsw button[data-v=stack]"); time.sleep(0.4); check("Stack: back to the overlay", c.ev("__rehab.state.view==='stack'"))
# ---------- borderline set and strictness
click(c, "#btnBack"); time.sleep(0.5)
c.ev("__submit([16,16,16])"); wait(c, "__rehab.state.screen==='result'", 20); time.sleep(1.5)
check("borderline: standard does not correct", S_(c)["findings"][0][1] == "borderline")
click(c, "#btnClin"); time.sleep(1.2)
check("borderline: clinician sees 'just past the threshold' note", c.ev("document.getElementById('det').textContent.includes('Just past the threshold')"))
def strict(name):
    click(c, f"#seg button[data-s={name}]"); wait(c, f"__rehab.state.strictness==='{name}' && !document.getElementById('seg').classList.contains('busy')", 15); time.sleep(0.5)
    return json.loads(c.ev("JSON.stringify({st:__rehab.state.result.findings[0].status, patient:document.getElementById('patientText').textContent, checked:[...document.querySelectorAll('#seg button')].filter(b=>b.getAttribute('aria-checked')==='true').map(b=>b.dataset.s)})"))
s1 = strict("strict"); check("strictness Strict: corrects the borderline set", s1["st"] == "error" and s1["checked"] == ["strict"] and "Bend your upper body" in s1["patient"])
s2 = strict("lenient"); check("strictness Lenient: leaves it alone", s2["st"] == "borderline" and s2["checked"] == ["lenient"])
s3 = strict("standard"); check("strictness Standard: back to borderline", s3["st"] == "borderline")
# strictness change while the server fails: recording is kept and a message is shown
c.ev("window.__rf=window.fetch; window.fetch=(...a)=>String(a[0]).includes('/api/session')?Promise.reject(new TypeError('x')):window.__rf(...a)")
click(c, "#seg button[data-s=strict]"); time.sleep(1.2)
check("strictness: failure keeps the set and explains", c.ev("document.getElementById('clinMeta').textContent.includes('recording is kept') && __rehab.state.result.frames.length>10 && !document.getElementById('seg').classList.contains('busy')"))
c.ev("window.fetch=window.__rf")
done(c, "G2")
